BEGIN TRANSACTION;

INSERT INTO posts (
  restaurant_id,
  title,
  content,
  password,
  created_at,
  updated_at
) VALUES
  (2667003, '와타요업 혼밥으로도 부담 없었어요 — 재방문 기록', '산책하다가 서구에 있는 와타요업에 방문했어요. 무난해 보이는 메뉴로 주문했는데 자극적이지 않아 부담 없이 먹기 좋았어요. 좌석 간격이 답답하지 않아 좋았습니다 다음에는 다른 메뉴도 먹어보고 싶습니다.', '1234', '2026-04-01 08:10:00.000000', '2026-04-01 11:30:00.000000'),
  (2582057, '적덕식당 메뉴 고민했던 이야기 — 재방문 기록', '친구와 함께 동구에 있는 적덕식당에 방문했어요. 처음 보는 메뉴를 골랐는데 특별히 강한 인상은 아니지만 편하게 먹기 좋았어요. 주차나 대기 여부는 미리 확인하면 좋을 것 같아요 취향과 방문 시간에 따라 만족도가 달라질 수 있겠습니다.', '1234', '2026-04-01 11:27:11.000000', '2026-04-01 11:27:11.000000'),
  (4077519, '아저씨돈까스 첫 방문이 생각보다 좋았어요 — 재방문 기록', '혼자 중구에 있는 아저씨돈까스에 방문했어요. 대표 메뉴를 주문했는데 양도 적당하고 전체적인 조화가 좋았습니다. 피크 시간에는 조금 붐빌 수 있어 보여요 근처에 다시 갈 일이 생기면 재방문할 생각이에요.', '1234', '2026-04-01 14:44:22.000000', '2026-04-01 14:44:22.000000'),
  (4077519, '아저씨돈까스 근처라면 한 번 들러볼 만해요', '비 오는 날 중구에 있는 아저씨돈까스에 방문했어요. 가장 많이 주문한다는 메뉴를 먹어봤는데 따뜻하게 나와서 마지막까지 맛있게 먹었어요. 주문 과정이 빠르고 어렵지 않았습니다 동네에서 편하게 방문할 곳으로 기억해 두려고요.', '1234', '2026-04-01 18:01:33.000000', '2026-04-01 18:01:33.000000'),
  (4077519, '아저씨돈까스 혼밥으로도 부담 없었어요', '주말 저녁에 중구에 있는 아저씨돈까스에 방문했어요. 무난해 보이는 메뉴로 주문했는데 식감이 좋고 생각보다 든든했습니다. 주차나 대기 여부는 미리 확인하면 좋을 것 같아요 비슷한 메뉴를 좋아한다면 한 번 방문해도 좋을 것 같아요.', '1234', '2026-04-01 20:18:44.000000', '2026-04-01 20:18:44.000000'),
  (2914558, '천복순대국밥 궁동점에서 편하게 식사했어요 — 재방문 기록', '주말 저녁에 유성구에 있는 천복순대국밥 궁동점에 방문했어요. 무난해 보이는 메뉴로 주문했는데 따뜻하게 나와서 마지막까지 맛있게 먹었어요. 매장 정리가 잘 되어 있어 편안했어요 비슷한 메뉴를 좋아한다면 한 번 방문해도 좋을 것 같아요.', '1234', '2026-04-02 09:35:55.000000', '2026-04-02 09:35:55.000000'),
  (2915383, '촌놈들연탄구이 본점 혼밥으로도 부담 없었어요 — 재방문 기록', '친구와 함께 유성구에 있는 촌놈들연탄구이 본점에 방문했어요. 무난해 보이는 메뉴로 주문했는데 간이 과하지 않고 재료 맛이 잘 느껴졌어요. 혼자 방문해도 눈치 보이지 않는 분위기였어요 동네에서 편하게 방문할 곳으로 기억해 두려고요.', '1234', '2026-04-02 12:52:06.000000', '2026-04-02 12:52:06.000000'),
  (2915691, '전주복집 근처라면 한 번 들러볼 만해요 — 재방문 기록', '퇴근 후 유성구에 있는 전주복집에 방문했어요. 무난해 보이는 메뉴로 주문했는데 간이 과하지 않고 재료 맛이 잘 느껴졌어요. 대화하면서 식사하기 괜찮은 분위기였습니다 전체적으로 만족스러워 주변 사람에게도 추천하고 싶어요.', '1234', '2026-04-02 16:09:17.000000', '2026-04-02 16:09:17.000000'),
  (2912260, '신흥초밥, 재방문하고 싶은 이유가 있었어요 — 재방문 기록', '가족과 함께 유성구에 있는 신흥초밥에 방문했어요. 대표 메뉴를 주문했는데 양도 적당하고 전체적인 조화가 좋았습니다. 직원분들의 응대는 친절한 편이었어요 동네에서 편하게 방문할 곳으로 기억해 두려고요.', '1234', '2026-04-02 18:26:28.000000', '2026-04-02 18:26:28.000000'),
  (2743291, '도덕봉가든에서 편하게 식사했어요 — 재방문 기록', '산책하다가 유성구에 있는 도덕봉가든에 방문했어요. 직원분께 추천받은 메뉴를 선택했는데 식감이 좋고 생각보다 든든했습니다. 직원분들의 응대는 친절한 편이었어요 다음에는 다른 메뉴도 먹어보고 싶습니다.', '1234', '2026-04-02 21:43:39.000000', '2026-04-02 21:43:39.000000'),
  (2912107, '바다가 솔직 후기와 메뉴 선택 팁 — 재방문 기록', '근처에 볼 일이 있어 유성구에 있는 바다가에 방문했어요. 가장 많이 주문한다는 메뉴를 먹어봤는데 전체적으로 무난하고 익숙한 맛이었어요. 주차나 대기 여부는 미리 확인하면 좋을 것 같아요 피크 시간을 피해 방문하면 더 편하게 즐길 수 있을 것 같아요.', '1234', '2026-04-03 11:00:50.000000', '2026-04-03 11:00:50.000000'),
  (2913377, '어가원 첫 방문이 생각보다 좋았어요 — 재방문 기록', '주말 저녁에 유성구에 있는 어가원에 방문했어요. 직원분께 추천받은 메뉴를 선택했는데 양도 적당하고 전체적인 조화가 좋았습니다. 주차나 대기 여부는 미리 확인하면 좋을 것 같아요 전체적으로 만족스러워 주변 사람에게도 추천하고 싶어요.', '1234', '2026-04-03 13:17:01.000000', '2026-04-03 13:17:01.000000'),
  (2912674, '유성즉석떡볶이 평일 방문 후기 — 재방문 기록', '친구와 함께 유성구에 있는 유성즉석떡볶이에 방문했어요. 가장 많이 주문한다는 메뉴를 먹어봤는데 양도 적당하고 전체적인 조화가 좋았습니다. 피크 시간에는 조금 붐빌 수 있어 보여요 전체적으로 만족스러워 주변 사람에게도 추천하고 싶어요.', '1234', '2026-04-03 16:34:12.000000', '2026-04-03 19:54:12.000000'),
  (2899380, '갑동숯불민물장어, 기대보다 만족도가 높았어요 — 재방문 기록', '산책하다가 유성구에 있는 갑동숯불민물장어에 방문했어요. 가장 많이 주문한다는 메뉴를 먹어봤는데 자극적이지 않아 부담 없이 먹기 좋았어요. 매장 정리가 잘 되어 있어 편안했어요 전체적으로 만족스러워 주변 사람에게도 추천하고 싶어요.', '1234', '2026-04-03 19:51:23.000000', '2026-04-03 19:51:23.000000'),
  (2915383, '촌놈들연탄구이 본점, 다음에도 같은 메뉴 먹고 싶어요', '근처에 볼 일이 있어 유성구에 있는 촌놈들연탄구이 본점에 방문했어요. 평소 좋아하던 메뉴를 골랐는데 양도 적당하고 전체적인 조화가 좋았습니다. 피크 시간에는 조금 붐빌 수 있어 보여요 다음에는 다른 메뉴도 먹어보고 싶습니다.', '1234', '2026-04-03 09:08:34.000000', '2026-04-03 09:08:34.000000'),
  (2912871, '그린베이커리, 다음에도 같은 메뉴 먹고 싶어요 — 재방문 기록', '산책하다가 유성구에 있는 그린베이커리에 방문했어요. 대표 메뉴를 주문했는데 기본에 충실한 맛이라 편하게 즐길 수 있었어요. 주문 과정이 빠르고 어렵지 않았습니다 비슷한 메뉴를 좋아한다면 한 번 방문해도 좋을 것 같아요.', '1234', '2026-04-04 11:25:45.000000', '2026-04-04 11:25:45.000000'),
  (2915383, '촌놈들연탄구이 본점 가족과 방문하기 괜찮았어요', '늦은 점심으로 유성구에 있는 촌놈들연탄구이 본점에 방문했어요. 대표 메뉴를 주문했는데 자극적이지 않아 부담 없이 먹기 좋았어요. 좌석 간격이 답답하지 않아 좋았습니다 전체적으로 만족스러워 주변 사람에게도 추천하고 싶어요.', '1234', '2026-04-04 14:42:56.000000', '2026-04-04 14:42:56.000000'),
  (2899380, '갑동숯불민물장어 가족과 방문하기 괜찮았어요', '근처에 볼 일이 있어 유성구에 있는 갑동숯불민물장어에 방문했어요. 가장 많이 주문한다는 메뉴를 먹어봤는데 따뜻하게 나와서 마지막까지 맛있게 먹었어요. 매장 정리가 잘 되어 있어 편안했어요 비슷한 메뉴를 좋아한다면 한 번 방문해도 좋을 것 같아요.', '1234', '2026-04-04 17:59:07.000000', '2026-04-04 17:59:07.000000'),
  (2912674, '유성즉석떡볶이, 재방문하고 싶은 이유가 있었어요', '늦은 점심으로 유성구에 있는 유성즉석떡볶이에 방문했어요. 대표 메뉴를 주문했는데 자극적이지 않아 부담 없이 먹기 좋았어요. 주차나 대기 여부는 미리 확인하면 좋을 것 같아요 비슷한 메뉴를 좋아한다면 한 번 방문해도 좋을 것 같아요.', '1234', '2026-04-04 20:16:18.000000', '2026-04-04 20:16:18.000000'),
  (2914558, '천복순대국밥 궁동점 대기 시간과 분위기 후기', '퇴근 후 유성구에 있는 천복순대국밥 궁동점에 방문했어요. 대표 메뉴를 주문했는데 전체적으로 무난하고 익숙한 맛이었어요. 직원분들의 응대는 친절한 편이었어요 피크 시간을 피해 방문하면 더 편하게 즐길 수 있을 것 같아요.', '1234', '2026-04-04 09:33:29.000000', '2026-04-04 09:33:29.000000'),
  (4077519, '아저씨돈까스에서 편하게 식사했어요', '친구와 함께 중구에 있는 아저씨돈까스에 방문했어요. 대표 메뉴를 주문했는데 양도 적당하고 전체적인 조화가 좋았습니다. 매장 정리가 잘 되어 있어 편안했어요 근처에 다시 갈 일이 생기면 재방문할 생각이에요.', '1234', '2026-04-05 12:50:40.000000', '2026-04-05 12:50:40.000000'),
  (2915383, '촌놈들연탄구이 본점 대기 시간이 길었던 후기', '근처에 볼 일이 있어 유성구에 있는 촌놈들연탄구이 본점에 방문했어요. 처음 보는 메뉴를 골랐는데 붐비는 시간이라 음식의 온도가 조금 아쉬웠어요. 좌석 간격이 답답하지 않아 좋았습니다 급하게 식사해야 할 때보다는 여유 있게 방문하는 편이 좋겠습니다.', '1234', '2026-04-05 16:07:51.000000', '2026-04-05 16:07:51.000000'),
  (2912957, '라꼬레, 재방문하고 싶은 이유가 있었어요 — 재방문 기록', '근처에 볼 일이 있어 유성구에 있는 라꼬레에 방문했어요. 가장 많이 주문한다는 메뉴를 먹어봤는데 따뜻하게 나와서 마지막까지 맛있게 먹었어요. 주차나 대기 여부는 미리 확인하면 좋을 것 같아요 전체적으로 만족스러워 주변 사람에게도 추천하고 싶어요.', '1234', '2026-04-05 18:24:02.000000', '2026-04-05 18:24:02.000000'),
  (2913800, '노랑물고기 본점 방문 전에 알아두면 좋은 점 — 재방문 기록', '평일 점심에 유성구에 있는 노랑물고기 본점에 방문했어요. 무난해 보이는 메뉴로 주문했는데 전체적으로 무난하고 익숙한 맛이었어요. 혼자 방문해도 눈치 보이지 않는 분위기였어요 다음 방문에는 다른 메뉴를 선택해 비교해 보고 싶어요.', '1234', '2026-04-05 21:41:13.000000', '2026-04-05 21:41:13.000000'),
  (2667003, '와타요업 대표 메뉴 먹어본 후기', '평일 점심에 서구에 있는 와타요업에 방문했어요. 처음 보는 메뉴를 골랐는데 식감이 좋고 생각보다 든든했습니다. 주문 과정이 빠르고 어렵지 않았습니다 동네에서 편하게 방문할 곳으로 기억해 두려고요.', '1234', '2026-04-05 10:58:24.000000', '2026-04-05 14:18:24.000000'),
  (2582534, '풍전삼계탕 첫 방문에서 느낀 장단점 — 재방문 기록', '가족과 함께 서구에 있는 풍전삼계탕에 방문했어요. 직원분께 추천받은 메뉴를 선택했는데 취향에 따라 평가가 조금 갈릴 수 있을 것 같아요. 대화하면서 식사하기 괜찮은 분위기였습니다 근처에 있다면 가볍게 방문하기 괜찮은 곳입니다.', '1234', '2026-04-06 13:15:35.000000', '2026-04-06 13:15:35.000000'),
  (2912674, '유성즉석떡볶이 혼밥으로도 부담 없었어요', '혼자 유성구에 있는 유성즉석떡볶이에 방문했어요. 직원분께 추천받은 메뉴를 선택했는데 기본에 충실한 맛이라 편하게 즐길 수 있었어요. 혼자 방문해도 눈치 보이지 않는 분위기였어요 근처에 다시 갈 일이 생기면 재방문할 생각이에요.', '1234', '2026-04-06 16:32:46.000000', '2026-04-06 16:32:46.000000'),
  (2866294, '대전밀면 대기 시간이 길었던 후기 — 재방문 기록', '근처에 볼 일이 있어 동구에 있는 대전밀면에 방문했어요. 직원분께 추천받은 메뉴를 선택했는데 가격을 생각하면 양이 조금 아쉽게 느껴졌습니다. 좌석 간격이 답답하지 않아 좋았습니다 한 번의 방문만으로 판단하기 어려워 다음에 다시 확인해 보려고 합니다.', '1234', '2026-04-06 19:49:57.000000', '2026-04-06 19:49:57.000000'),
  (2912957, '라꼬레 솔직 후기: 장단점이 분명했어요', '근처에 볼 일이 있어 유성구에 있는 라꼬레에 방문했어요. 평소 좋아하던 메뉴를 골랐는데 기대했던 것보다 간이 조금 강하게 느껴졌어요. 좌석 간격이 답답하지 않아 좋았습니다 급하게 식사해야 할 때보다는 여유 있게 방문하는 편이 좋겠습니다.', '1234', '2026-04-06 09:06:08.000000', '2026-04-06 09:06:08.000000'),
  (3473362, '향수정원 대표 메뉴 먹어본 후기 — 재방문 기록', '평일 점심에 옥천군에 있는 향수정원에 방문했어요. 무난해 보이는 메뉴로 주문했는데 따뜻하게 나와서 마지막까지 맛있게 먹었어요. 혼자 방문해도 눈치 보이지 않는 분위기였어요 다음에는 다른 메뉴도 먹어보고 싶습니다.', '1234', '2026-04-06 11:23:19.000000', '2026-04-06 11:23:19.000000'),
  (2913583, '왕가 대기 시간과 분위기 후기 — 재방문 기록', '가족과 함께 유성구에 있는 왕가에 방문했어요. 대표 메뉴를 주문했는데 다른 메뉴를 먹으면 인상이 달라질 수도 있겠어요. 혼자 방문해도 눈치 보이지 않는 분위기였어요 다음 방문에는 다른 메뉴를 선택해 비교해 보고 싶어요.', '1234', '2026-04-07 14:40:30.000000', '2026-04-07 14:40:30.000000'),
  (2912122, '비바릴리 도안점, 재방문하고 싶은 이유가 있었어요 — 재방문 기록', '주말 저녁에 유성구에 있는 비바릴리 도안점에 방문했어요. 가장 많이 주문한다는 메뉴를 먹어봤는데 간이 과하지 않고 재료 맛이 잘 느껴졌어요. 매장 정리가 잘 되어 있어 편안했어요 동네에서 편하게 방문할 곳으로 기억해 두려고요.', '1234', '2026-04-07 17:57:41.000000', '2026-04-07 17:57:41.000000'),
  (2737979, '권인순 갈비김치찌개에서 편하게 식사했어요 — 재방문 기록', '늦은 점심으로 유성구에 있는 권인순 갈비김치찌개에 방문했어요. 대표 메뉴를 주문했는데 따뜻하게 나와서 마지막까지 맛있게 먹었어요. 좌석 간격이 답답하지 않아 좋았습니다 전체적으로 만족스러워 주변 사람에게도 추천하고 싶어요.', '1234', '2026-04-07 20:14:52.000000', '2026-04-07 20:14:52.000000'),
  (2914687, '선화동실비식당, 이런 분께 잘 맞을 것 같아요 — 재방문 기록', '근처에 볼 일이 있어 중구에 있는 선화동실비식당에 방문했어요. 처음 보는 메뉴를 골랐는데 양과 간은 무난한 편이었습니다. 좌석 간격이 답답하지 않아 좋았습니다 피크 시간을 피해 방문하면 더 편하게 즐길 수 있을 것 같아요.', '1234', '2026-04-07 09:31:03.000000', '2026-04-07 09:31:03.000000'),
  (4077519, '아저씨돈까스 음식이 깔끔해서 좋았습니다', '산책하다가 중구에 있는 아저씨돈까스에 방문했어요. 직원분께 추천받은 메뉴를 선택했는데 양도 적당하고 전체적인 조화가 좋았습니다. 주문 과정이 빠르고 어렵지 않았습니다 비슷한 메뉴를 좋아한다면 한 번 방문해도 좋을 것 같아요.', '1234', '2026-04-07 12:48:14.000000', '2026-04-07 12:48:14.000000'),
  (3548479, '모닝트리 한 번 방문해 본 느낌 — 재방문 기록', '가족과 함께 유성구에 있는 모닝트리에 방문했어요. 가장 많이 주문한다는 메뉴를 먹어봤는데 양과 간은 무난한 편이었습니다. 좌석 간격이 답답하지 않아 좋았습니다 피크 시간을 피해 방문하면 더 편하게 즐길 수 있을 것 같아요.', '1234', '2026-04-08 16:05:25.000000', '2026-04-08 16:05:25.000000'),
